widget.solution:
def predict_at(p, t):
    # 1 where p >= t, else 0
    return [1 if v >= t else 0 for v in p]

def confusion_counts(y, p, t):
    # return (tp, fp, fn, tn)
    tp = fp = fn = tn = 0
    for yi, ci in zip(y, predict_at(p, t)):
        if ci == 1 and yi == 1:
            tp += 1
        elif ci == 1:
            fp += 1
        elif yi == 1:
            fn += 1
        else:
            tn += 1
    return (tp, fp, fn, tn)

