widget.solution:
def best_threshold(y, p, cost_fp, cost_fn):
    # scan t = 0.00, 0.01, ..., 1.00; return (t, cost) of the cheapest
    best_t, best_cost = None, None
    for i in range(101):
        t = i / 100
        fp = sum(1 for yi, pi in zip(y, p) if pi >= t and yi == 0)
        fn = sum(1 for yi, pi in zip(y, p) if pi < t and yi == 1)
        cost = fp * cost_fp + fn * cost_fn
        if best_cost is None or cost < best_cost:
            best_t, best_cost = t, cost
    return (best_t, best_cost)
